import itertools

def get_knight_moves(r, c, rows, cols):
    moves = [
        (r+2, c+1), (r+2, c-1), (r-2, c+1), (r-2, c-1),
        (r+1, c+2), (r+1, c-2), (r-1, c+2), (r-1, c-2)
    ]
    return [(nr, nc) for nr, nc in moves if 0 <= nr < rows and 0 <= nc < cols]

def solve_small(rows, cols):
    # Knight graph
    adj = {}
    for r in range(rows):
        for c in range(cols):
            adj[(r, c)] = get_knight_moves(r, c, rows, cols)

    all_squares = list(itertools.product(range(rows), range(cols)))

    # We want to find the min number of knights Horst can place
    # Horst's goal: maximize K
    # Queenie's goal: minimize K

    # This is a game. We can use minimax for very small boards.
    memo = {}

    def get_state(knights, queens):
        return (tuple(sorted(knights)), tuple(sorted(queens)))

    def can_horst_move(knights, queens):
        for s in all_squares:
            if s not in knights and s not in queens:
                # Knight at s must not attack any previous knights
                if all(s not in adj[k] for k in knights):
                    yield s

    def can_queenie_move(knights, queens):
        for s in all_squares:
            if s not in knights and s not in queens:
                yield s

    def minimax(knights, queens, turn_horst):
        state = get_state(knights, queens)
        if state in memo:
            return memo[state]

        if turn_horst:
            moves = list(can_horst_move(knights, queens))
            if not moves:
                return len(knights)

            # Horst wants to maximize K
            res = -1
            for m in moves:
                res = max(res, minimax(knights | {m}, queens, False))
            memo[state] = res
            return res
        else:
            moves = list(can_queenie_move(knights, queens))
            if not moves:
                # Game ends when someone cannot move
                # If it's Queenie's turn and she can't move, the game ends.
                return len(knights)

            # Queenie wants to minimize K
            res = float('inf')
            for m in moves:
                res = min(res, minimax(knights, queens | {m}, True))
            memo[state] = res
            return res

    return minimax(set(), set(), True)

print(f"2x2: {solve_small(2, 2)}")
print(f"3x3: {solve_small(3, 3)}")
print(f"4x2: {solve_small(4, 2)}")
print(f"4x3: {solve_small(4, 3)}")

