import networkx as nx

def get_knight_matching(rows, cols):
    G = nx.Graph()
    for r in range(rows):
        for c in range(cols):
            for nr, nc in get_knight_moves(r, c, rows, cols):
                G.add_edge((r, c), (nr, nc))
    matching = nx.max_weight_matching(G, maxcardinality=True)
    return len(matching)

